import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Riduzione di più crediti","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbea.md","filePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbea.md"}`),a={name:`lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbea.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="riduzione-di-piu-crediti" tabindex="-1">Riduzione di più crediti <a class="header-anchor" href="#riduzione-di-piu-crediti" aria-label="Permalink to “Riduzione di più crediti”">​</a></h1><p>Se una persona ha diversi crediti con varie scadenze può realizzare i diversi crediti con un&#39;unica riscossione (ad esempio accordandosi con i creditori oppure cedendo i vari crediti ad una banca o società finanziaria).</p><p>Quindi fra le parti bisogna accordarsi, considerando il regime ad interesse e sconto composto, sul tasso da applicare.</p><blockquote><p><strong>Nota:</strong> Da notare che i crediti di cui parliamo non influiscono con il loro tasso: se il credito deriva da una vendita con pagamento differito allora il tasso proprio non esiste, e se si tratta del recupero di un prestito noi lavoriamo sul montante e quindi il tasso, essendo già compreso, è per noi indifferente.</p></blockquote><p>Invece le parti contraenti dovranno accordarsi sul tasso da applicare per spostare i capitali nel tempo; ciò dà luogo a due soluzioni:</p><ul><li><p>i contraenti fissano la data dell&#39;unico pagamento, quindi ne determineremo l&#39;importo; diremo che abbiamo la <strong>riduzione di più crediti ad una scadenza data</strong></p></li><li><p>i contraenti fissano l&#39;importo dell&#39;unico pagamento, quindi ne determineremo la scadenza; quindi dovremo <strong>determinare la scadenza</strong></p></li><li><p><a href="./nbeaa.html">importo a scadenza data</a></p></li><li><p><a href="./nbeab.html">ricerca della scadenza</a></p></li></ul>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};